'use strict';
// Standalone portfolio simulation. No production code, endpoints, or credentials.
const STORAGE_KEY = 'crm-portfolio-demo-v1';
const STAGES = ['New', 'Follow-up', 'Proposal', 'Won'];
const CHECKLIST = ['Onboarding details received', 'Documents verified', 'Filing prepared', 'Approval recorded', 'Delivery complete'];
const SEED = [
 {id:'d1',name:'Maya Chen',company:'Juniper Studio',email:'maya@example.com',service:'Company formation',source:'Website',owner:'Alex Morgan',stage:'New',value:1200,quote:0,payment:0,followup:'',ops:0,events:[{text:'Website enquiry captured and routed to Alex.',at:'Seed example'}]},
 {id:'d2',name:'Jordan Ellis',company:'Northstar Labs',email:'jordan@example.com',service:'Annual compliance',source:'Referral',owner:'Sam Rivera',stage:'New',value:650,quote:0,payment:0,followup:'',ops:0,events:[{text:'Referral enquiry created.',at:'Seed example'}]},
 {id:'d3',name:'Riley Park',company:'Maple & Co',email:'riley@example.com',service:'Company formation',source:'Social campaign',owner:'Alex Morgan',stage:'Follow-up',value:1500,quote:0,payment:0,followup:'2026-12-01',ops:0,events:[{text:'Consultation completed; follow-up scheduled.',at:'Seed example'}]},
 {id:'d4',name:'Casey Brooks',company:'Orbit Design',email:'casey@example.com',service:'Tax filing support',source:'Website',owner:'Sam Rivera',stage:'Proposal',value:900,quote:900,payment:0,followup:'',ops:0,events:[{text:'Demo proposal prepared for $900.',at:'Seed example'}]},
 {id:'d5',name:'Taylor Reed',company:'Pinecone Digital',email:'taylor@example.com',service:'Company formation',source:'Referral',owner:'Alex Morgan',stage:'Won',value:1200,quote:1200,payment:1200,followup:'',ops:2,events:[{text:'Demo deal won and handed off to operations.',at:'Seed example'}]},
 {id:'d6',name:'Avery Quinn',company:'Meadow Works',email:'avery@example.com',service:'Annual compliance',source:'Social campaign',owner:'Sam Rivera',stage:'Proposal',value:750,quote:750,payment:0,followup:'',ops:0,events:[{text:'Demo proposal prepared for $750.',at:'Seed example'}]}
];
function validState(value){return Array.isArray(value)&&value.length===SEED.length&&value.every((x,i)=>x.id===SEED[i].id&&STAGES.includes(x.stage)&&Number.isFinite(x.value)&&Number.isFinite(x.quote)&&Number.isFinite(x.payment)&&Number.isInteger(x.ops)&&x.ops>=0&&x.ops<=CHECKLIST.length&&Array.isArray(x.events)&&x.events.every(e=>typeof e.text==='string'&&typeof e.at==='string'));}
function load(){try{const value=JSON.parse(localStorage.getItem(STORAGE_KEY));if(validState(value))return value;}catch{}return structuredClone(SEED);}
let leads=load(),currentTab='pipeline',activeId=null,returnFocus=null;
const $=id=>document.getElementById(id);
const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=v=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(v);
function persist(){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(leads));}catch{$('announcement').textContent='Browser storage unavailable. Changes last for this page session only.';}}
function addEvent(lead,text){lead.events.unshift({text,at:new Date().toLocaleString()});persist();render();}
function render(){
 const won=leads.filter(x=>x.stage==='Won');const open=leads.filter(x=>x.stage!=='Won');
 $('stats').innerHTML=[['Open opportunities',open.length,'Fictional demo pipeline'],['Open pipeline value',money(open.reduce((a,x)=>a+x.value,0)),'Illustrative deal estimates'],['Demo receipts',money(leads.reduce((a,x)=>a+x.payment,0)),'Simulated, not real payments'],['Delivery files',won.length,'Paid deals in operations']].map(x=>`<div class="stat"><span>${x[0]}</span><strong>${x[1]}</strong><small>${x[2]}</small></div>`).join('');
 const term=$('search').value.toLowerCase();const source=$('source-filter').value;const filtered=leads.filter(x=>(!source||x.source===source)&&`${x.name} ${x.company} ${x.service}`.toLowerCase().includes(term));
 $('result-count').textContent=`${filtered.length} demo leads`;
 $('board').innerHTML=STAGES.map(stage=>{const rows=filtered.filter(x=>x.stage===stage);return `<section class="column" aria-label="${stage} stage"><h2 class="column-title">${stage}<span class="count">${rows.length}</span></h2>${rows.map(x=>`<button class="lead-card" data-lead="${x.id}" aria-label="Open ${esc(x.name)} at ${esc(x.company)}"><span class="chip ${x.source==='Website'?'blue':x.source==='Referral'?'gold':''}">${esc(x.source)}</span><h3>${esc(x.name)}</h3><p>${esc(x.company)} · ${esc(x.service)}</p><span class="value">${money(x.value)}</span><div class="card-footer"><span>${esc(x.owner)}</span><span>${stage==='Won'?'Delivery active':x.followup?'Follow-up set':'Open details ↗'}</span></div></button>`).join('')||'<p class="empty">No matching leads in this stage.</p>'}</section>`;}).join('');
 $('ops-table').innerHTML=won.map(x=>`<tr><td><strong>${esc(x.company)}</strong><br>${esc(x.name)}</td><td>${esc(x.service)}</td><td>${x.ops}/${CHECKLIST.length} complete</td><td>${esc(CHECKLIST[x.ops]||'Delivered')}</td><td><button class="table-action" data-ops="${x.id}">Open file →</button></td></tr>`).join('')||'<tr><td colspan="5">Mark a paid demo deal Won to create a delivery file.</td></tr>';
 $('all-activity').innerHTML=leads.flatMap(x=>x.events.map(e=>`<li><strong>${esc(x.company)}</strong> · ${esc(e.text)}<small>${esc(e.at)}</small></li>`)).join('');
}
function tab(name){currentTab=name;document.querySelectorAll('[data-tab]').forEach(b=>{const selected=b.dataset.tab===name;b.classList.toggle('active',selected);b.setAttribute('aria-pressed',String(selected));});['pipeline','operations','activity'].forEach(x=>$(x+'-view').hidden=x!==name);$('view-title').textContent={pipeline:'Sales pipeline',operations:'Operations desk',activity:'Activity log'}[name];$('view-description').textContent={pipeline:'One view of the customer journey, from first contact to a paid deal.',operations:'A clear handoff from a paid deal to a completed service.',activity:'The context behind every change in the customer journey.'}[name];}
function showModal(lead,ops=false){activeId=lead.id;returnFocus=document.activeElement;$('modal').hidden=false;document.body.style.overflow='hidden';renderDialog(lead,ops);$('close').focus();}
function closeModal(){$('modal').hidden=true;document.body.style.overflow='';const lead=activeId;activeId=null;const target=returnFocus?.isConnected?returnFocus:document.querySelector(`[data-lead="${lead}"]`)||$('guided');target.focus();}
function renderDialog(x,ops=false){
 $('dialog-chip').textContent=ops?'OPERATIONS FILE':x.stage+' · DEMO LEAD';$('dialog-title').textContent=x.company;$('dialog-subtitle').textContent=x.name+' · '+x.service;
 const info=`<div class="detail-grid"><div class="detail-item"><small>CONTACT / FICTIONAL</small><strong>${esc(x.email)}</strong></div><div class="detail-item"><small>ASSIGNED CONSULTANT</small><strong>${esc(x.owner)}</strong></div><div class="detail-item"><small>PROPOSAL</small><strong>${x.quote?money(x.quote):'Not prepared'}</strong></div><div class="detail-item"><small>DEMO PAYMENT</small><strong>${x.payment?money(x.payment)+' simulated':'Not recorded'}</strong></div></div>`;
 const controls=ops?`<h3 class="section-label">DELIVERY CHECKLIST</h3><p class="status-note">Complete each step in order. No documents are uploaded and no real filings occur.</p><ul class="checklist">${CHECKLIST.map((s,i)=>`<li><input id="op-${i}" type="checkbox" data-check="${i}" ${i<x.ops?'checked':''} ${i!==x.ops?'disabled':''}><label for="op-${i}">${s}</label></li>`).join('')}</ul>${x.ops===CHECKLIST.length?'<div class="message">Demo delivery complete. The customer journey is finished.</div>':''}`:`<h3 class="section-label">MOVE THE DEAL FORWARD</h3><form id="stage-form" class="form-row"><label>Pipeline stage<select id="stage">${STAGES.map(s=>`<option ${s===x.stage?'selected':''}>${s}</option>`).join('')}</select></label><label>Next follow-up<input id="followup" type="date" value="${esc(x.followup)}"></label><button class="button small" type="submit">Update stage</button></form><form id="quote-form" class="form-row"><label>Demo quote (USD)<input id="quote-value" type="number" min="1" max="100000" step="1" value="${x.quote||x.value}" required></label><button class="button secondary small" type="submit" ${x.payment?'disabled':''}>Prepare demo quote</button></form><div class="form-row"><button class="button small" id="pay" ${!x.quote||x.payment?'disabled':''}>${x.payment?'Demo payment recorded':'Simulate full payment'}</button>${x.stage==='Won'?'<button class="button secondary small" id="open-ops">Open delivery file →</button>':''}</div><p class="status-note">No payment processor, email, or messaging service is called.</p>`;
 $('dialog-content').innerHTML=info+controls+'<div id="feedback" role="status" aria-live="polite"></div><h3 class="section-label">ACTIVITY TIMELINE</h3><ul class="activity">'+x.events.map(e=>`<li>${esc(e.text)}<small>${esc(e.at)}</small></li>`).join('')+'</ul>';
 if(ops){document.querySelectorAll('[data-check]').forEach(c=>c.addEventListener('change',()=>{const i=Number(c.dataset.check);if(i===x.ops){x.ops++;addEvent(x,'Demo operations step completed: '+CHECKLIST[i]+'.');renderDialog(x,true);const next=document.querySelector(`[data-check="${x.ops}"]`);(next||$('close')).focus();}}));return;}
 const feedback=(message,error=false)=>{$('feedback').innerHTML=`<div class="message ${error?'error':''}">${esc(message)}</div>`;};
 $('stage-form').addEventListener('submit',e=>{e.preventDefault();const stage=$('stage').value;const date=$('followup').value;if(x.stage==='Won'&&stage!=='Won')return feedback('A won deal stays in delivery in this demo. Reset to explore it again.',true);if(stage==='Follow-up'&&!date)return feedback('Choose a follow-up date before moving to Follow-up.',true);if(stage==='Proposal'&&!x.quote)return feedback('Prepare a demo quote before moving to Proposal.',true);if(stage==='Won'&&(!x.quote||x.payment<x.quote))return feedback('Prepare a quote and simulate its full payment before marking Won.',true);if(stage===x.stage&&date===x.followup)return feedback('No changes to save.');const isNewWin=stage==='Won'&&x.stage!=='Won';x.stage=stage;x.followup=date;addEvent(x,`Stage updated to ${stage}.${isNewWin?' Delivery file created.':''}`);renderDialog(x);feedback(isNewWin?'Deal won. The operations file is ready.':'Demo stage updated.');});
 $('quote-form').addEventListener('submit',e=>{e.preventDefault();const value=Number($('quote-value').value);if(x.payment)return;if(!Number.isFinite(value)||value<1||value>100000)return feedback('Enter a demo amount between $1 and $100,000.',true);x.quote=value;x.value=value;addEvent(x,'Demo proposal prepared for '+money(value)+'.');renderDialog(x);feedback('Quote prepared locally. Nothing was sent.');});
 $('pay').addEventListener('click',()=>{if(!x.quote||x.payment)return;x.payment=x.quote;addEvent(x,'Simulated full payment received: '+money(x.payment)+'.');renderDialog(x);feedback('Simulated payment recorded once. You can now mark the deal Won.');});
 $('open-ops')?.addEventListener('click',()=>{tab('operations');renderDialog(x,true);});
}
document.addEventListener('click',e=>{const lead=e.target.closest('[data-lead]');const ops=e.target.closest('[data-ops]');const t=e.target.closest('[data-tab]');if(lead)showModal(leads.find(x=>x.id===lead.dataset.lead));if(ops)showModal(leads.find(x=>x.id===ops.dataset.ops),true);if(t)tab(t.dataset.tab);});
$('search').addEventListener('input',render);$('source-filter').addEventListener('change',render);$('close').addEventListener('click',closeModal);$('modal').addEventListener('click',e=>{if(e.target===$('modal'))closeModal();});
document.addEventListener('keydown',e=>{if($('modal').hidden)return;if(e.key==='Escape'){closeModal();return;}if(e.key==='Tab'){const list=[...$('modal').querySelectorAll('button:not(:disabled),input:not(:disabled),select:not(:disabled),[tabindex="0"]')].filter(x=>x.getClientRects().length);const first=list[0],last=list.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
$('reset').addEventListener('click',()=>{if(!confirm('Reset fictional demo records and clear your local demo changes?'))return;leads=structuredClone(SEED);persist();$('search').value='';$('source-filter').value='';render();tab('pipeline');$('announcement').textContent='Fictional demo reset.';});
$('guided').addEventListener('click',()=>{tab('pipeline');showModal(leads.find(x=>x.id==='d1'));});
render();tab('pipeline');
